 if(corp)return 'doanh-nghiep-'+corp[1];
 if(/^\/demo\/(?:ban-hang\/cua-hang-online|dich-vu\/(?:cua-hang-laptop|tram-sac-vinfast))(?:\/|$)/i.test(path))return 'dich-vu-5';
 if(/^\/demo\/dich-vu\/mua-lan-su-rong(?:\/|$)/i.test(path))return 'dich-vu-6';
 return '';
