function serviceSeoPageHtml(page){
 const base='https://hoangvuongtech.com';
 const canonical=base+'/'+page.slug+'/';
 const escj=v=>esc(String(v??''));
 const faq=(page.faq||[]).map(x=>({'@type':'Question','name':x[0],'acceptedAnswer':{'@type':'Answer','text':x[1]}}));
 const graph={'@context':'https://schema.org','@graph':[{'@type':'WebPage','@id':canonical+'#webpage','url':canonical,'name':page.title,'description':page.desc,'isPartOf':{'@id':base+'/#website'},'about':{'@id':canonical+'#service'}},{'@type':'Service','@id':canonical+'#service','name':page.h1,'description':page.desc,'provider':{'@id':base+'/#organization'},'areaServed':{'@type':'Country','name':'Việt Nam'},'offers':{'@type':'Offer','priceCurrency':'VND','price':'1499000','description':'Giá từ 1.499.000đ/năm; khách mới ưu đãi 500.000đ theo chương trình áp dụng; tên miền và hosting theo gói.'}},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'HoangVuongTech','item':base+'/'},{'@type':'ListItem','position':2,'name':page.h1,'item':canonical}]},{'@type':'FAQPage','mainEntity':faq}]};
 const related=Object.values(SEO_SERVICE_PAGES).filter(x=>x.slug!==page.slug).slice(0,6);
 return `<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escj(page.title)}</title><meta name="description" content="${escj(page.desc)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="${canonical}"><meta property="og:type" content="website"><meta property="og:site_name" content="HoangVuongTech"><meta property="og:title" content="${escj(page.title)}"><meta property="og:description" content="${escj(page.desc)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${base}/assets/marketing-demo.webp"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${escj(page.title)}"><meta name="twitter:description" content="${escj(page.desc)}"><link rel="stylesheet" href="/assets/hoangvuongtech.css?v=20.9.20.8"><link rel="icon" type="image/png" sizes="16x16" href="/favicons/favicon-16x16.png"><script type="application/ld+json">${JSON.stringify(graph)}</script><style>.seo-page-hero{padding:84px 0 64px;background:linear-gradient(135deg,#eff6ff,#fff)}.seo-page-hero .hv-wrap{max-width:1100px}.seo-page-hero h1{max-width:900px;font-size:clamp(38px,5vw,64px);line-height:1.04;margin:14px 0 20px;color:#0b1f3a}.seo-page-hero p{max-width:800px;font-size:18px;line-height:1.75;color:#52627a}.seo-badges{display:flex;flex-wrap:wrap;gap:10px;margin:24px 0}.seo-badges span{padding:10px 14px;border:1px solid #dbe7ff;border-radius:999px;background:#fff;font-weight:700;color:#17345f}.seo-content{max-width:900px;margin:auto}.seo-content article{padding:26px 0;border-bottom:1px solid #e7edf5}.seo-content article h2{font-size:29px;margin:0 0 12px;color:#0b1f3a}.seo-content article p{font-size:17px;line-height:1.8;color:#52627a}.seo-related{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.seo-related a{display:block;padding:20px;border:1px solid #dce6f4;border-radius:16px;background:#fff;font-weight:800;color:#135fe8;text-decoration:none}.seo-cta{padding:34px;border-radius:24px;background:#0f67ff;color:#fff;text-align:center}.seo-cta h2{margin-top:0;color:#fff}.seo-cta p{color:#eaf2ff}.seo-cta .hv-btn{background:#fff!important;color:#0f67ff!important;border-color:#fff!important}.seo-page-faq details{max-width:900px;margin:10px auto;padding:18px 20px;border:1px solid #dfe7f2;border-radius:14px;background:#fff}.seo-page-faq summary{font-weight:800;cursor:pointer}.seo-page-faq p{line-height:1.7;color:#52627a}@media(max-width:760px){.seo-page-hero{padding:52px 0 42px}.seo-related{grid-template-columns:1fr}.seo-page-hero h1{font-size:40px}.seo-cta .hv-btn{width:100%;max-width:360px;margin:18px auto 0}}</style></head><body><header class="hv-head"><div class="hv-wrap hv-nav"><a class="hv-brand" href="/"><b>HOANGVUONG</b><strong>TECH</strong><span>Website & giải pháp số</span></a><nav><a href="/thiet-ke-website/">Thiết kế website</a><a href="/templates/">Kho giao diện</a><a class="hv-btn small" href="/templates/">Chọn mẫu & dùng thử 1 ngày</a></nav></div></header><main><section class="seo-page-hero"><div class="hv-wrap"><span class="eyebrow">${escj(page.eyebrow)}</span><h1>${escj(page.h1)}</h1><p>${escj(page.lead)}</p><div class="seo-badges">${(page.benefits||[]).map(x=>`<span>✓ ${escj(x)}</span>`).join('')}</div><div class="hero-actions"><a class="hv-btn" href="/templates/">Chọn mẫu & dùng thử 1 ngày</a><a class="hv-btn ghost" href="/templates/">Xem mẫu từ 1.499K/năm</a></div></div></section><section class="hv-section"><div class="hv-wrap seo-content">${(page.sections||[]).map(x=>`<article><h2>${escj(x[0])}</h2><p>${escj(x[1])}</p></article>`).join('')}</div></section><section class="hv-section alt"><div class="hv-wrap"><div class="section-title"><span>TRỌN GÓI & DỄ BẮT ĐẦU</span><h2>Chọn mẫu trước, trải nghiệm thật rồi mới đăng ký</h2><p>Gói website có tên miền, hosting và Trang quản trị theo chính sách áp dụng. Khách hàng mới được ưu đãi 500.000đ theo chương trình hiện hành.</p></div><div class="steps"><article><i>1</i><h3>Chọn giao diện</h3><p>Xem mẫu theo lĩnh vực và chọn bố cục phù hợp.</p></article><article><i>2</i><h3>Dùng thử 1 ngày</h3><p>Kích hoạt website thử và vào Trang quản trị.</p></article><article><i>3</i><h3>Đăng ký khi phù hợp</h3><p>Nhận ưu đãi khách mới theo chương trình.</p></article><article><i>4</i><h3>Bàn giao sử dụng</h3><p>Hoàn thiện tên miền và website chính thức.</p></article></div></div></section><section class="hv-section"><div class="hv-wrap"><div class="seo-cta"><h2>Muốn biết website có dễ dùng thật không?</h2><p>Không cần đoán. Chọn một mẫu và trải nghiệm website miễn phí trong 1 ngày trước khi đăng ký.</p><a class="hv-btn" href="/templates/">Chọn mẫu & dùng thử ngay →</a></div></div></section><section class="hv-section seo-page-faq"><div class="hv-wrap"><div class="section-title"><span>HỎI ĐÁP</span><h2>Câu hỏi thường gặp</h2></div>${(page.faq||[]).map(x=>`<details><summary>${escj(x[0])}</summary><p>${escj(x[1])}</p></details>`).join('')}</div></section><section class="hv-section alt"><div class="hv-wrap"><div class="section-title"><span>GIẢI PHÁP LIÊN QUAN</span><h2>Xem thêm dịch vụ thiết kế website</h2></div><div class="seo-related">${related.map(x=>`<a href="/${escj(x.slug)}/">${escj(x.h1)} →</a>`).join('')}<a href="/templates/">Kho giao diện website →</a></div></div></section></main><footer class="hv-footer"><div class="hv-wrap"><b>HOANGVUONGTECH</b><span>Website chuyên nghiệp · Quản trị đơn giản · Hỗ trợ tận tâm</span></div></footer></body></html>`;
}

const PRO_DEMO_KEYS=new Set(['blog-ca-nhan-1','blog-ca-nhan-2','doanh-nghiep-1','doanh-nghiep-2','dich-vu-5','dich-vu-6']);
function proDemoKeyFromPath(path){
 const p=String(path||'').replace(/\/+$/,'')||'/';
 if(/^\/demo\/blog-ca-nhan\/mau-1(?:\/|$)/i.test(p))return 'blog-ca-nhan-1';
 if(/^\/demo\/blog-ca-nhan\/mau-2(?:\/|$)/i.test(p))return 'blog-ca-nhan-2';
 if(/^\/demo\/doanh-nghiep\/mau-1(?:\/|$)/i.test(p))return 'doanh-nghiep-1';
 if(/^\/demo\/doanh-nghiep\/mau-2(?:\/|$)/i.test(p))return 'doanh-nghiep-2';
 if(/^\/demo\/(?:ban-hang\/cua-hang-online|dich-vu\/(?:cua-hang-laptop|tram-sac-vinfast))(?:\/|$)/i.test(p))return 'dich-vu-5';
 if(/^\/demo\/dich-vu\/mua-lan-su-rong(?:\/|$)/i.test(p))return 'dich-vu-6';
 return '';
}
