function rEsc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function realImg(src,alt,cls=''){return `<img class="${cls}" src="${rEsc(src)}" alt="${rEsc(alt)}" loading="lazy" referrerpolicy="no-referrer">`}
function realCard(a,p,variant=''){return `<article class="rcard ${variant}"><a class="rimg" href="${p}/bai-viet/${a.slug}/">${realImg(a.img,a.title)}</a><div class="rbody"><span>${rEsc(a.cat)}</span><h3><a href="${p}/bai-viet/${a.slug}/">${rEsc(a.title)}</a></h3><p>${rEsc(a.excerpt)}</p></div></article>`}
function catArticles(c,cat,n=3){return c.articles.filter(a=>a.cat===cat).slice(0,n)}

function injectHvtSalesChat(html){const src='<script src="/assets/sales-chat.js?v=20.9.26.9" defer></script>';const out=String(html||'');return out.includes('/assets/sales-chat.js')?out:out.replace('</body>',src+'</body>')}

function sourceNote(){return `<small class="photo-note">Ảnh demo sử dụng ảnh chụp thực tế từ Unsplash. Nội dung được biên soạn thành bài mẫu hoàn chỉnh; phần số liệu/nghiệp vụ có nguồn tham khảo công khai bên dưới.</small>`}function realTop(d){
 const q=String(d||'');
 const m=/^dich-vu-(\d+)$/.exec(q);
 const group=m?'DỊCH VỤ · MẪU '+m[1]:/^blog-ca-nhan-/.test(q)?'BLOG CÁ NHÂN':/^doanh-nghiep-/.test(q)?'DOANH NGHIỆP':'ĐANG XEM DEMO';
 const category=/^dich-vu-/.test(q)?'/templates/dich-vu/':/^blog-ca-nhan-/.test(q)?'/templates/blog-ca-nhan/':/^doanh-nghiep-/.test(q)?'/templates/doanh-nghiep/':'/templates/';
 const bar=`<div class="nr-demo-bar"><div class="nr-demo-inner"><b>ĐANG XEM ${group}</b><span>Chọn giao diện phù hợp với bạn</span><div class="nr-demo-actions"><div class="nr-demo-devices" aria-label="Xem trên thiết bị"><button type="button" class="active" data-demo-device="desktop" title="Xem trên PC">▰ <span>PC</span></button><button type="button" data-demo-device="tablet" title="Xem trên Tablet">▯ <span>Tablet</span></button><button type="button" data-demo-device="mobile" title="Xem trên Mobile">▯ <span>Mobile</span></button></div><a href="${category}">Kho mẫu</a><a class="nr-demo-cta" data-demo-external="1" href="https://hoangvuongtech.com/?template=${encodeURIComponent(q)}#dang-ky" target="_blank" rel="noopener">Chọn mẫu này</a></div></div></div>`;
 const js=`<script>(function(){const q=new URLSearchParams(location.search);if(q.get('nr_frame')==='1'){document.body.classList.add('nr-demo-framed');return}document.addEventListener('DOMContentLoaded',function(){const buttons=[...document.querySelectorAll('[data-demo-device]')];let stage=null;function closeStage(){if(stage){stage.remove();stage=null}document.body.classList.remove('nr-device-open')}function frameUrl(){const u=new URL(location.href);u.searchParams.set('nr_frame','1');return u.toString()}function setMode(mode){buttons.forEach(b=>b.classList.toggle('active',b.dataset.demoDevice===mode));if(mode==='desktop'){closeStage();return}closeStage();stage=document.createElement('div');stage.className='nr-device-stage nr-device-'+mode;const label=document.createElement('div');label.className='nr-device-label';label.textContent=mode==='tablet'?'Tablet · 820px':'Mobile · 390px';const frame=document.createElement('iframe');frame.className='nr-device-frame';frame.src=frameUrl();frame.title='Xem trước giao diện '+mode;stage.append(label,frame);document.body.appendChild(stage);document.body.classList.add('nr-device-open')}buttons.forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.demoDevice)));setMode('desktop')})})();</script>`;
 return bar+js;
}
function researchBox(c){const k=String(c?.kind||'');if(k==='industrial')return `<aside class="research-box"><b>Nguồn tham khảo chuyên môn</b><p>Nội dung technical journal được biên soạn dựa trên tài liệu công khai của NIST về smart manufacturing/data analytics và OSHA về Lockout/Tagout. Không sao chép nguyên văn nguồn.</p><div><a href="https://www.nist.gov/programs-projects/data-analytics-smart-manufacturing-systems" target="_blank" rel="noopener">NIST · Smart Manufacturing ↗</a><a href="https://www.osha.gov/control-hazardous-energy/program" target="_blank" rel="noopener">OSHA · LOTO Program ↗</a></div></aside>`;if(k==='ev')return `<aside class="research-box"><b>Dữ liệu tham khảo thị trường EV</b><p>Số liệu thị trường sạc dùng dữ liệu công khai từ IEA Global EV Outlook 2026. Nội dung tư vấn trong demo chỉ để minh họa cấu trúc website.</p><div><a href="https://www.iea.org/reports/global-ev-outlook-2026/electric-vehicle-charging-chap-6-and-10" target="_blank" rel="noopener">IEA · Electric vehicle charging 2026 ↗</a></div></aside>`;if(k==='corporate')return `<aside class="research-box"><b>Nguồn đọc thêm</b><p>Phần dữ liệu và vận hành tham khảo các nguyên tắc data-driven decision making được NIST công bố; case study là tình huống demo biên soạn riêng.</p><div><a href="https://www.nist.gov/programs-projects/data-analytics-smart-manufacturing-systems" target="_blank" rel="noopener">NIST · Data Analytics ↗</a></div></aside>`;return ''}
function navCats(c){return `<nav class="catnav">${c.cats.map(x=>`<a href="#${encodeURIComponent(x)}">${rEsc(x)}</a>`).join('')}</nav>`}
